1	import { AlertCircle, RefreshCw } from "lucide-react";
2	import { Component, type ErrorInfo, type ReactNode } from "react";
3	import { useRouteError } from "react-router-dom";
4	import { Button } from "./ui/button";
5	
6	interface Props {
7	  children: ReactNode;
8	  fallback?: ReactNode;
9	}
10	
11	interface State {
12	  hasError: boolean;
13	  error: Error | null;
14	}
15	
16	export class ErrorBoundary extends Component<Props, State> {
17	  constructor(props: Props) {
18	    super(props);
19	    this.state = { hasError: false, error: null };
20	  }
21	
22	  static getDerivedStateFromError(error: Error): State {
23	    return { hasError: true, error };
24	  }
25	
26	  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
27	    console.error("ErrorBoundary caught an error:", error, errorInfo);
28	  }
29	
30	  handleReset = () => {
31	    this.setState({ hasError: false, error: null });
32	    window.location.reload();
33	  };
34	
35	  render() {
36	    if (this.state.hasError) {
37	      if (this.props.fallback) {
38	        return this.props.fallback;
39	      }
40	
41	      return (
42	        <div className="flex items-center justify-center min-h-screen bg-background">
43	          <div className="max-w-md w-full p-6 space-y-4">
44	            <div className="flex items-center gap-3 text-destructive">
45	              <AlertCircle className="w-8 h-8" />
46	              <h1 className="text-2xl font-bold">Something went wrong</h1>
47	            </div>
48	
49	            <p className="text-foreground/70">
50	              An unexpected error occurred. This could be due to a network issue or a problem with the application.
51	            </p>
52	
53	            {this.state.error && (
54	              <details className="bg-muted p-3 rounded-md text-sm">
55	                <summary className="cursor-pointer font-medium mb-2">Error details</summary>
56	                <pre className="whitespace-pre-wrap break-words text-xs text-foreground/60">{this.state.error.message}</pre>
57	              </details>
58	            )}
59	
60	            <Button onClick={this.handleReset} className="w-full gap-2">
61	              <RefreshCw className="w-4 h-4" />
62	              Reload Application
63	            </Button>
64	          </div>
65	        </div>
66	      );
67	    }
68	
69	    return this.props.children;
70	  }
71	}
